    image_patch = ImagePatch(image)
    sandwiches = image_patch.find("sandwich")
    tomatoes = image_patch.find("tomato")

    if not sandwiches or not tomatoes:
        return image_patch

    sandwich_patches = []
    for sandwich in sandwiches:
        for tomato in tomatoes:
            if is_in_front_of(sandwich, tomato):
                sandwich_patches.append(sandwich)

    if not sandwich_patches:
        return image_patch

    sandwich_patches.sort(key=lambda s: s.horizontal_center + s.width / 2)
    return sandwich_patches[-1]

